package com.hotel.dao.impl;
import com.hotel.dao.RoomDao;import com.hotel.dto.*;import com.hotel.exception.DataAccessException;import com.hotel.util.DBConnection;import java.sql.*;import java.time.LocalDate;import java.util.*;
public class RoomDaoImpl implements RoomDao{
 public List<RoomTypeOptionDto> findActiveRoomTypes(){String q="SELECT room_type_id,type_code,type_name,max_adults,max_children FROM room_types WHERE is_active=1 ORDER BY type_name";List<RoomTypeOptionDto>x=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next())x.add(new RoomTypeOptionDto(r.getLong(1),r.getString(2),r.getString(3),r.getInt(4),r.getInt(5)));return x;}catch(SQLException e){throw new DataAccessException("Unable to load room types",e);}}
 public List<AvailableRoomDto> searchAvailable(LocalDate checkIn,LocalDate checkOut,Long typeId,int adults,int children,Integer floor){String q="SELECT rm.room_id,rm.room_number,rm.floor_number,rt.type_code,rt.type_name,rt.bed_type,rt.max_adults,rt.max_children,rm.operational_status,rm.cleaning_status FROM rooms rm JOIN room_types rt ON rt.room_type_id=rm.room_type_id WHERE rm.is_active=1 AND rt.is_active=1 AND rm.operational_status='AVAILABLE' AND rm.cleaning_status='INSPECTED' AND (? IS NULL OR rm.room_type_id=?) AND rt.max_adults>=? AND rt.max_children>=? AND (? IS NULL OR rm.floor_number=?) AND NOT EXISTS(SELECT 1 FROM room_assignments ra WHERE ra.room_id=rm.room_id AND ra.is_current=1 AND ra.unassigned_at IS NULL) ORDER BY rt.type_name,rm.floor_number,rm.room_number";List<AvailableRoomDto>x=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){if(typeId==null){p.setNull(1,Types.BIGINT);p.setNull(2,Types.BIGINT);}else{p.setLong(1,typeId);p.setLong(2,typeId);}p.setInt(3,adults);p.setInt(4,children);if(floor==null){p.setNull(5,Types.INTEGER);p.setNull(6,Types.INTEGER);}else{p.setInt(5,floor);p.setInt(6,floor);}try(ResultSet r=p.executeQuery()){while(r.next()){Number f=(Number)r.getObject(3);x.add(new AvailableRoomDto(r.getLong(1),r.getString(2),f==null?null:f.intValue(),r.getString(4),r.getString(5),r.getString(6),r.getInt(7),r.getInt(8),r.getString(9),r.getString(10),checkIn,checkOut));}}return x;}catch(SQLException e){throw new DataAccessException("Unable to find available rooms",e);}}
}
